CREATE TABLE parent (id integer PRIMARY KEY, code text UNIQUE, plain text);
-- child a: nullable, non-unique fk -> pk
CREATE TABLE ch_a (id integer PRIMARY KEY, pid integer NULL REFERENCES parent(id));
-- child b: not-null, non-unique fk -> pk
CREATE TABLE ch_b (id integer PRIMARY KEY, pid integer NOT NULL REFERENCES parent(id));
-- child c: nullable, unique fk -> pk
CREATE TABLE ch_c (id integer PRIMARY KEY, pid integer NULL UNIQUE REFERENCES parent(id));
-- child d: not-null, unique fk -> pk
CREATE TABLE ch_d (id integer PRIMARY KEY, pid integer NOT NULL UNIQUE REFERENCES parent(id));
-- child e: fk -> unique (non-pk) column
CREATE TABLE ch_e (id integer PRIMARY KEY, pcode text REFERENCES parent(code));
-- child f: fk -> plain (non-unique) column
CREATE TABLE ch_f (id integer PRIMARY KEY, pplain text REFERENCES parent(plain));
-- self reference
CREATE TABLE node (id integer PRIMARY KEY, parent_id integer REFERENCES node(id));
''')
c.commit(); c.close(); print('ok')
